CREATE SEQUENCE "PackageRefSeq" START 1;
CREATE TABLE "DocumentPackage" ("id" UUID NOT NULL,"packageRef" TEXT NOT NULL,"invoiceRef" TEXT,"supplierDisplayName" TEXT,"status" TEXT NOT NULL DEFAULT 'draft',"checklistVersion" INTEGER NOT NULL DEFAULT 1,"version" INTEGER NOT NULL DEFAULT 1,"createdBy" UUID NOT NULL,"submittedBy" UUID,"submittedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DocumentPackage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PackageVisit" ("packageId" UUID NOT NULL,"visitId" UUID NOT NULL,CONSTRAINT "PackageVisit_pkey" PRIMARY KEY ("packageId","visitId"));
CREATE TABLE "PackageItem" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"category" TEXT NOT NULL,"position" INTEGER NOT NULL,"notApplicableReason" TEXT,"hoCheck" TEXT NOT NULL DEFAULT 'unchecked',"hoNote" TEXT,CONSTRAINT "PackageItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DocumentFile" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"category" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"sha256" CHAR(64) NOT NULL,"size" INTEGER NOT NULL,"originalName" TEXT NOT NULL,"scanStatus" TEXT NOT NULL DEFAULT 'pending_scan',"uploadedBy" UUID NOT NULL,"uploadedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMP(3),CONSTRAINT "DocumentFile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PackageCorrection" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"reason" TEXT NOT NULL,"categories" JSONB NOT NULL,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resolvedAt" TIMESTAMP(3),"responseNote" TEXT,CONSTRAINT "PackageCorrection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ErpMilestone" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"type" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"dataManRef" TEXT,"erpOccurredAt" TIMESTAMP(3),"confirmedAt" TIMESTAMP(3),"confirmedBy" UUID,"reversedAt" TIMESTAMP(3),"reversalReason" TEXT,"source" TEXT NOT NULL DEFAULT 'manual_staff_confirmation',CONSTRAINT "ErpMilestone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Reminder" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"note" TEXT NOT NULL,"recipient" TEXT NOT NULL DEFAULT 'Plant Head',"channel" TEXT NOT NULL DEFAULT 'pending',"recordedBy" UUID NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Reminder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PackageHistory" ("id" UUID NOT NULL,"packageId" UUID NOT NULL,"action" TEXT NOT NULL,"detail" TEXT,"source" TEXT NOT NULL DEFAULT 'app',"actorId" UUID NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PackageHistory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DocumentPackage_packageRef_key" ON "DocumentPackage"("packageRef");
CREATE INDEX "DocumentPackage_status_updatedAt_idx" ON "DocumentPackage"("status","updatedAt");
CREATE UNIQUE INDEX "PackageVisit_visitId_key" ON "PackageVisit"("visitId");
CREATE UNIQUE INDEX "PackageItem_packageId_category_key" ON "PackageItem"("packageId","category");
CREATE UNIQUE INDEX "PackageItem_packageId_position_key" ON "PackageItem"("packageId","position");
CREATE UNIQUE INDEX "DocumentFile_storageKey_key" ON "DocumentFile"("storageKey");
CREATE INDEX "DocumentFile_packageId_category_deletedAt_idx" ON "DocumentFile"("packageId","category","deletedAt");
CREATE UNIQUE INDEX "ErpMilestone_packageId_type_key" ON "ErpMilestone"("packageId","type");
CREATE INDEX "PackageHistory_packageId_recordedAt_idx" ON "PackageHistory"("packageId","recordedAt");
